pfp=sz=>{const i=avInfo();return`<span class="pfp pfp-${sz}" data-av="${sz}">${i.url?`<img src="${esc(i.url)}" alt="Foto de perfil" decoding=async>`:`<span class=pfp-i aria-hidden=true>${avInit()}</span>`}</span>`},
avMsg=t=>{const e=$('#avmsg');if(e)e.textContent=t},avDrop=()=>{if(U.avp){URL.revokeObjectURL(U.avp.url);U.avp=null}},
pfCard=()=>{const i=avInfo();if(!i.cloud)return'<h2>Foto de perfil</h2><p class=sub>Inicia sesión con tu cuenta para guardar tu foto y verla en todos tus dispositivos.</p>';const has=!!i.url,dis=i.busy?' disabled':'';return`<h2>Foto de perfil</h2><div class=pf-row>${pfp('l')}<div class=pf-acts><button class="btn sm" data-a=avpick${dis}>${has?'Cambiar foto':'Subir foto'}</button>${has?`<button class="btn g sm" data-a=avdel${dis}>Eliminar foto</button>`:''}</div></div><div class=sub id=avmsg role=status aria-live=polite>${i.busy?'Guardando…':i.st==='loading'?'Cargando foto…':i.err?esc(i.err):'JPG, PNG o WebP · se recorta en cuadrado · se sincroniza en tus dispositivos'}</div>`};
function head(){const d=new Date(today()+'T12:00:00'),h=Math.floor(nowMin()/60),g=h<12?'Buenos días.':h<19?'Buenas tardes.':'Buenas noches.',st=streak();return`<div class=top><div style="display:flex;gap:12px;align-items:center">${avInfo().url?pfp('m'):'<div class=av>◎</div>'}<div><h1>Mi Centro de Control</h1><div class=sub>Construyendo mi independencia y mi empresa</div><div class=sub style="color:var(--a)">${msg()}</div></div></div><div style="text-align:right"><div><b>${g.replace('.',S.name?', '+S.name+'.':'.')}</b> <span class=sub id=ck></span></div><div class=sub>${d.toLocaleDateString('es-CO',{weekday:'long',day:'numeric',month:'long'})} · ${st?`🔥 ${st} días de constancia`:'Hoy puedes empezar tu racha'}</div></div></div>${S.demo?'<div class=demo>Datos de ejemplo: reemplázalos o empieza desde cero en Ajustes.</div>':''}${!S.setupComplete&&!S.demo?'<div class=demo>Configura tu perfil, tus metas y tus prioridades para adaptar el sistema a tu vida. <button class=btn data-a=setup>Configurar ahora</button></div>':''}`}
function render(){$('#nv').innerHTML='<div class=lg>'+pfp('s')+'<span>Centro de Control</span></div>'+NAV.map(n=>`<button class="${S.view===n[0]?'on':''}" data-a=go data-i=${n[0]}><span>${n[1]}</span>${n[2]}</button>`).join('');$('#mn').innerHTML=(S.view==='inicio'?head():'')+P[S.view]();clock();Sync.avatarLoad()}
const clock=()=>{const e=$('#ck');if(e)e.textContent=new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit',timeZone:TZ})};setInterval(clock,1e4);
function fgForm(existing){const f=existing||{n:'',t:'',date:'',goal:''};modal(`<h2>${existing?'Editar meta financiera':'Nueva meta financiera'}</h2><form id=fm><label>Nombre de la meta</label><input name=n required maxlength="90" value="${esc(f.n)}" placeholder="Ej. Motocicleta"><label>Importe objetivo (COP)</label><input name=t type=number min="1" step="1" required value="${esc(f.t)}"><label>Fecha objetivo</label><input name=date type=date value="${esc(f.date||'')}"><label>Objetivo vinculado</label><select name=goal><option value="">Ninguno</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${f.goal===g.id?'selected':''}>${esc(g.t)}</option>`).join('')}</select><div class=amsg id=fgmsg role=alert></div><div class=tabs style="margin-top:14px"><button class=btn>Guardar meta</button><button type=button class="btn g" data-a=close>Cancelar</button></div></form>`);$('#fm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget)),t=Number(o.t);if(!o.n.trim()||!Number.isFinite(t)||t<=0){$('#fgmsg').textContent='Escribe un nombre y un importe objetivo válido.';return}if(o.date&&o.date<'2000-01-01'){ $('#fgmsg').textContent='Revisa la fecha objetivo.';return}if(existing)Object.assign(existing,{n:o.n.trim(),t,date:o.date,goal:o.goal});else S.fg.push({id:uid(),n:o.n.trim(),t,date:o.date,goal:o.goal});closeM();save();render();toast(existing?'Meta actualizada':'Meta creada')}}
function budgetForm(existing){const b=existing||{category:'',limit:'',month:U.finMonth||today().slice(0,7)};modal(`<h2>${existing?'Editar presupuesto':'Crear presupuesto mensual'}</h2><p class=sub>El gasto utilizado se calcula automáticamente a partir de los movimientos de la categoría y el mes elegidos.</p><form id=fm><label>Categoría exacta del gasto</label><input name=category required maxlength="70" value="${esc(b.category)}" placeholder="Ej. Transporte"><label>Límite mensual (COP)</label><input name=limit type=number min="1" step="1" required value="${esc(b.limit)}"><label>Mes del presupuesto</label><input name=month type=month required value="${esc(b.month||today().slice(0,7))}"><div class=amsg id=budgetmsg role=alert></div><div class=tabs style="margin-top:14px"><button class=btn>Guardar presupuesto</button><button type=button class="btn g" data-a=close>Cancelar</button></div></form>`);$('#fm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget)),limit=Number(o.limit),category=o.category.trim();if(!category||!Number.isFinite(limit)||limit<=0||!/^\d{4}-\d{2}$/.test(o.month)){ $('#budgetmsg').textContent='Revisa la categoría, el límite y el mes.';return}const duplicate=S.budgets.find(x=>x.id!==b.id&&x.month===o.month&&x.category.toLowerCase()===category.toLowerCase());if(duplicate){$('#budgetmsg').textContent='Ya existe un presupuesto para esa categoría y ese mes. Edita el existente.';return}if(existing)Object.assign(existing,{category,limit,month:o.month});else S.budgets.push({id:uid(),category,limit,month:o.month});U.finMonth=o.month;closeM();save();render();toast(existing?'Presupuesto actualizado':'Presupuesto creado')}}
/* ===== acciones ===== */
const done=(id)=>{const t=S.tasks.find(x=>x.id===id);return t};
const A={close:closeM,go:i=>{U.wl=false;S.view=i;try{localStorage.setItem('cc.view',i)}catch(e){}Repo.save();render();scrollTo(0,0)},
tst:i=>{const[id,st]=i.split('|'),t=done(id);if(st==='completada'){return form('Resultado: '+t.t,[{k:'res',l:'¿Qué resultado obtuviste?'},{k:'note',l:'Nota',t:'area'},{k:'next',l:'Siguiente paso (crea una nueva acción)'},{k:'ev',l:'Evidencia (opcional)'}],o=>{t.st='completada';t.doneAt=today();t.res=o.res;t.note=o.note;t.ev=o.ev;if(o.next)S.tasks.push({id:uid(),t:o.next,k:t.k,cat:t.cat,due:addD(today(),1),min:30,pri:t.pri,st:'pendiente',doneAt:'',goal:t.goal,dep:'',from:t.id,created:today()});toast('✓ Resultado registrado: progreso actualizado')})}t.st=st;if(st==='pospuesta')t.due=addD(today(),1);save();render();toast('Estado: '+st)},
tdel:i=>{S.tasks=S.tasks.filter(x=>x.id!==i);save();render()},hdone:i=>{(S.hl[today()]=S.hl[today()]||[]).push(i);save();render();toast('✓ Hábito registrado')},
hab:i=>{const L=S.hl[today()]=S.hl[today()]||[],k=L.indexOf(i);k<0?L.push(i):L.splice(k,1);save();render()},
addhab:()=>habForm(),edithab:i=>habForm(S.habits.find(h=>h.id===i)),delhab:i=>{if(confirm('¿Eliminar este hábito? Deja de contar en tu progreso.')){S.habits=S.habits.filter(h=>h.id!==i);S.sch.forEach(b=>{if(b.hab===i)b.hab=''});save();render()}},
addtk:()=>form('Nueva tarea',[{k:'t',l:'Tarea',r:1},{k:'k',l:'Área',t:'select',o:[['proy','Proyecto'],['ceo','Empresa'],['vida','Vida'],['fin','Finanzas']]},{k:'cat',l:'Categoría de proyecto',t:'select',o:PA},{k:'due',l:'Fecha límite',t:'date',v:today()},{k:'min',l:'Minutos',t:'number',v:30},{k:'pri',l:'Prioridad',t:'select',o:[['3','Alta'],['2','Media'],['1','Baja']]},{k:'goal',l:'Objetivo',t:'select',o:[['','Ninguno'],...S.goals.map(g=>[g.id,g.t])]}],o=>S.tasks.push({...o,id:uid(),min:+o.min,pri:+o.pri,st:'pendiente',doneAt:'',dep:'',created:today()})),
setup:()=>{const p=S.pf||{};modal(`<h2>Configura tu Centro de Control</h2><p class=sub>Completa lo que sepas ahora. Puedes cambiarlo después desde Ajustes.</p><form id=fm><label>Cómo quieres que te llamemos</label><input name=name value="${esc(S.name||'')}"><label>Saldo inicial disponible (COP)</label><input name=cap0 type=number min=0 step=1 value="${Number(S.cap0||0)}"><label>Meta total de ahorro (COP)</label><input name=goalSave type=number min=1 step=1 value="${Number(S.goalSave||2000000)}"><label>Meta diaria de cigarrillos (si aplica)</label><input name=cigGoal type=number min=0 step=1 value="${Number(S.cig.goal??10)}"><label>Nivel de entrenamiento</label><select name=level>${[['1','Principiante'],['2','Intermedio'],['3','Avanzado']].map(([v,l])=>`<option value="${v}" ${Number(S.level)===Number(v)?'selected':''}>${l}</option>`).join('')}</select><label>Tiempo para entrenar (minutos)</label><select name=min>${[15,25,30,45].map(v=>`<option value="${v}" ${Number(S.min)===v?'selected':''}>${v}</option>`).join('')}</select><label>Peso (kg, opcional)</label><input name=peso type=number min=1 step=0.1 value="${esc(p.peso||'')}"><label>Altura (cm, opcional)</label><input name=altura type=number min=1 step=0.1 value="${esc(p.altura||'')}"><label>Objetivo físico</label><input name=obj value="${esc(p.obj||'')}" placeholder="Ej. mejorar condición física"><label>Equipamiento disponible</label><input name=equipo value="${esc(p.equipo||'')}" placeholder="Ej. ninguno, silla, bandas"><label>Restricciones o lesiones</label><input name=restr value="${esc(p.restr||'')}"><div class=amsg id=setupmsg role=alert></div><div class=tabs><button class=btn>Guardar configuración</button><button type=button class="btn g" data-a=close>Más tarde</button></div></form>`);$('#fm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget)),num=(v,d=0)=>v===''?d:Number(v);if(!Number.isFinite(num(o.cap0))||num(o.cap0)<0||!Number.isFinite(num(o.goalSave))||num(o.goalSave)<=0||!Number.isFinite(num(o.cigGoal))||num(o.cigGoal)<0){$('#setupmsg').textContent='Revisa los importes y las metas numéricas.';return}S.name=o.name.trim();S.cap0=num(o.cap0);S.goalSave=num(o.goalSave,2000000);S.cig.goal=num(o.cigGoal,10);S.level=num(o.level,2);S.min=num(o.min,30);S.pf={...S.pf,peso:o.peso?num(o.peso):'',altura:o.altura?num(o.altura):'',obj:o.obj.trim(),equipo:o.equipo.trim(),restr:o.restr.trim()};S.setupComplete=true;closeM();save();render();toast('Configuración guardada') }},addtx:()=>txForm(),txedit:i=>{const x=S.tx.find(t=>t.id===i);if(x)txForm(x)},txdel:i=>{S.tx=S.tx.filter(x=>x.id!==i);save();render();toast('Movimiento eliminado y saldo recalculado')},
addco:()=>form('Nueva empresa',[{k:'n',l:'Nombre',r:1},{k:'sec',l:'Sector'},{k:'ct',l:'Contacto'},{k:'tel',l:'Teléfono'},{k:'em',l:'Correo'},{k:'loc',l:'Ubicación'},{k:'src',l:'Fuente'},{k:'st',l:'Estado',t:'select',o:ST},{k:'date',l:'Fecha de contacto',t:'date'},{k:'next',l:'Próximo seguimiento',t:'date'},{k:'pb',l:'Problema detectado'},{k:'int',l:'Interés (1-5)',t:'number',v:3},{k:'notes',l:'Notas',t:'area'}],o=>{S.co.push({...o,id:uid(),int:+o.int,created:today()});toast('Prospecto registrado: Empresa actualizada')}),
codel:i=>{S.co=S.co.filter(x=>x.id!==i);save();render()},mvp:()=>{S.mvp=(S.mvp||0)+1;save();render();toast('MVP registrado')},
addpr:()=>form('Problema detectado',[{k:'t',l:'Problema',r:1},{k:'who',l:'Quién lo tiene'},{k:'ev',l:'Evidencia'},{k:'fr',l:'Frecuencia'},{k:'im',l:'Impacto'},{k:'sol',l:'Solución propuesta'},{k:'emp',l:'Empresas afectadas'},{k:'v',l:'Validación',t:'select',o:['Detectado','Validando','Validado','Descartado']}],o=>S.pr.push({...o,id:uid(),created:today()})),
addev:()=>form('Nuevo evento',[{k:'t',l:'Título',r:1},{k:'date',l:'Fecha',t:'date',v:U.cd},{k:'h',l:'Hora',t:'time',v:'09:00'},{k:'k',l:'Tipo',t:'select',o:['Reunión','Entrevista','Universidad','Trabajo','Empresa']}],o=>S.ev.push({...o,id:uid()})),
cd:i=>{U.cd=i;render()},cmv:i=>{const[y,m]=U.cm.split('-').map(Number),d=new Date(y,m-1+ +i,1);U.cm=iso(d).slice(0,7);render()},cvw:i=>{U.cv=i;render()},rpt:i=>{U.rp=i;render()},
addg:()=>form('Nuevo objetivo',[{k:'t',l:'Descripción',r:1},{k:'l',l:'Nivel',t:'select',o:['Anual','Trimestral','Mensual','Semanal','Diario']},{k:'parent',l:'Alimenta a',t:'select',o:[['','Ninguno (visión)'],...S.goals.map(g=>[g.id,g.l+': '+g.t])]},{k:'date',l:'Fecha límite',t:'date'},{k:'pri',l:'Prioridad',t:'select',o:[['3','Alta'],['2','Media'],['1','Baja']]},{k:'cat',l:'Categoría',t:'select',o:['Empresa','Finanzas','Proyecto','Vida','Salud']},{k:'src',l:'Métrica del sistema (opcional)',t:'select',o:[['','Ninguna'],...Object.keys(MS)]},{k:'mt',l:'Meta de la métrica',t:'number'},{k:'ms',l:'Hitos (separados por coma)'}],o=>S.goals.push({id:uid(),t:o.t,l:o.l,parent:o.parent,date:o.date,pri:+o.pri,cat:o.cat,src:o.src,mt:+o.mt||0,ms:o.ms?o.ms.split(',').map(x=>({t:x.trim(),done:false})).filter(m=>m.t):[],est:'Pendiente'})),
gdel:i=>{S.goals=S.goals.filter(g=>g.id!==i&&g.parent!==i);save();render()},
addb:()=>blockForm(),editb:i=>blockForm(S.sch.find(b=>b.id===i)),bdel:i=>{S.sch=S.sch.filter(b=>b.id!==i);save();render()},
rdemo:async()=>{if(!confirm('¿Restablecer datos demo? Se reemplazan tus datos.'))return;if(!await Sync.backupOk('antes de cargar datos demo'))return;S=demo();save();render()},zero:async()=>{if(!confirm('¿Borrar todo y empezar desde cero?'))return;if(!await Sync.backupOk('antes de empezar desde cero'))return;S=blank();S.view='inicio';save();render()},
syncnow:()=>Sync.syncNow(),logout:()=>Sync.logout(),login:()=>Sync.showLogin(),importlegacy:()=>Sync.importLegacy(),dellegacy:()=>Sync.deleteLegacy(),snaps:()=>Sync.snapshots(),acct:()=>Sync.account(),
exp:()=>{const b=new Blob([JSON.stringify(S,null,1)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='centro-de-control.json';a.click()},
startrun:startRun,setdone:()=>{const e=run.p.ex[run.i];run.log.push({n:e.n,set:run.set,r:e.r});if(run.set>=e.s){run.i++;run.set=1;run.rest=run.p.ex[run.i]?60:0}else{run.set++;run.rest=45}modal(runUI())},skiprest:()=>{run.rest=0},endrun:()=>{run.i=run.p.ex.length;modal(runUI())},
dst:i=>{const[id,st]=i.split('|'),b=S.sch.find(x=>x.id===id),L=S.dl[today()]=S.dl[today()]||{};if(st==='done'&&b.k==='ej'&&!S.wk.some(w=>w.date===today())){startRun();return}const was=L[id],n0=today();if(st==='reset')delete L[id];else L[id]=st;if(was==='resched'&&st!=='resched')S.tasks=S.tasks.filter(t=>!(t.rs===id+n0&&!t.doneAt));if(was==='done'&&st!=='done'){const n=today();if(b.hab&&S.hl[n])S.hl[n]=S.hl[n].filter(x=>x!==b.hab);S.tasks=S.tasks.filter(t=>t.auto!==id+n)}if(st==='done'){const n=today();if(b.hab){const H=S.hl[n]=S.hl[n]||[];if(!H.includes(b.hab))H.push(b.hab)}if(b.goal&&!(b.hab&&(S.habits.find(h=>h.id===b.hab)||{}).goal===b.goal)&&!S.tasks.some(t=>t.auto===id+n))S.tasks.push({id:uid(),t:b.t,k:'vida',cat:'',due:n,min:30,pri:2,st:'completada',doneAt:n,goal:b.goal,dep:'',created:n,auto:id+n})}if(st==='resched'&&!S.tasks.some(t=>t.rs===id+n0))S.tasks.push({rs:id+n0,orig:n0,id:uid(),t:'Reprogramada: '+b.t,k:'vida',cat:'',due:addD(today(),1),min:30,pri:2,st:'pendiente',doneAt:'',goal:'',dep:'',created:today()});save();render();toast(st==='done'?'✓ Actividad cumplida':st==='miss'?'Marcada como incumplida':st==='reset'?'Estado restablecido':'Reprogramada para mañana')},
avpick:()=>{if(avInfo().busy)return;const i=document.createElement('input');i.type='file';i.accept='image/jpeg,image/png,image/webp';i.onchange=()=>{const f=i.files[0];if(!f)return;avMsg('Procesando imagen…');Sync.avatarPrepare(f).then(p=>{avDrop();U.avp=p;modal(`<h2>Vista previa</h2><div style="text-align:center"><span class="pfp pfp-xl"><img src="${p.url}" alt="Vista previa de tu nueva foto"></span></div><p class=sub id=avm role=status aria-live=polite style="text-align:center;margin-top:10px">¿Usar esta foto de perfil?</p><div class=tabs style="margin-top:14px;justify-content:center"><button class=btn data-a=avok>Usar esta foto</button><button class="btn g" data-a=avno>Cancelar</button></div>`);avMsg('')}).catch(e=>avMsg(e.message))};i.click()},
avno:()=>{avDrop();closeM()},
avok:()=>{const p=U.avp;if(!p)return;const b=$('#mb [data-a=avok]'),m=$('#avm');b.disabled=true;b.textContent='Subiendo…';m.style.color='';m.textContent='Subiendo tu foto…';Sync.avatarSave(p.blob).then(()=>{avDrop();closeM();toast('✓ Foto de perfil actualizada')}).catch(e=>{b.disabled=false;b.textContent='Reintentar';m.style.color='var(--r)';m.textContent=e.message})},
avdel:()=>{if(!confirm('¿Eliminar tu foto de perfil? Volverás al avatar predeterminado.'))return;avMsg('Eliminando…');Sync.avatarRemove().then(()=>toast('Foto eliminada')).catch(e=>avMsg(e.message))},
planman:()=>{S.tasks.filter(t=>!t.doneAt&&t.due&&t.due<today()).forEach(t=>t.due=addD(today(),1));save();render();toast('Vencidas movidas a mañana')},
cig:()=>{const v=$('#cn').value;if(v===''||!Number.isFinite(+v)||+v<0)return toast('Escribe una cantidad válida');S.cig.log[today()]={n:+v,g:S.cig.goal,note:$('#cnt').value};save();render();toast(+v<=S.cig.goal?'✓ Meta cumplida hoy':'Registrado: +'+(v-S.cig.goal)+' sobre la meta')},
viceadd:()=>form('Añadir vicio o hábito perjudicial',[{k:'name',l:'Nombre (ej. cigarrillos, apuestas, redes sociales)',r:1},{k:'category',l:'Categoría (opcional)'},{k:'mode',l:'Objetivo',t:'select',v:'quit',o:[['quit','Dejarlo por completo'],['reduce','Reducirlo gradualmente']]},{k:'unit',l:'Unidad (veces, minutos, unidades, dinero)',v:'veces',r:1},{k:'target',l:'Máximo permitido por día (solo para reducir)',t:'number',v:1}],o=>{if(!o.name.trim())return toast('Escribe el nombre del hábito');if(o.mode==='reduce'&&(o.target===''||!Number.isFinite(+o.target)||+o.target<0))return toast('Define una meta válida para reducirlo');S.vices=S.vices||[];S.vices.push({id:uid(),name:o.name.trim(),category:o.category.trim()||'Personalizado',mode:o.mode,unit:o.unit.trim()||'veces',target:o.mode==='reduce'?+o.target:0,logs:{}});toast('Hábito añadido')}),
viceedit:i=>{const v=(S.vices||[]).find(x=>x.id===i);if(!v)return;form('Editar hábito',[{k:'name',l:'Nombre',v:v.name,r:1},{k:'category',l:'Categoría',v:v.category||''},{k:'mode',l:'Objetivo',t:'select',v:v.mode||'quit',o:[['quit','Dejarlo por completo'],['reduce','Reducirlo gradualmente']]},{k:'unit',l:'Unidad',v:v.unit||'veces',r:1},{k:'target',l:'Máximo permitido por día',t:'number',v:v.target??0}],o=>{if(!o.name.trim())return toast('Escribe el nombre del hábito');if(o.mode==='reduce'&&(o.target===''||!Number.isFinite(+o.target)||+o.target<0))return toast('Define una meta válida');Object.assign(v,{name:o.name.trim(),category:o.category.trim()||'Personalizado',mode:o.mode,unit:o.unit.trim()||'veces',target:o.mode==='reduce'?+o.target:0});toast('Hábito actualizado')})},
vicelog:i=>{const v=(S.vices||[]).find(x=>x.id===i);if(!v)return;const prior=v.logs[today()]||{};form('Registrar: '+v.name,[{k:'date',l:'Fecha',t:'date',v:today(),r:1},{k:'amount',l:`Cantidad (${v.unit||'veces'}; usa 0 si no ocurrió)`,t:'number',v:prior.amount??0,r:1},{k:'note',l:'Observación opcional',t:'area',v:prior.note||''}],o=>{const n=Number(o.amount);if(!o.date||!Number.isFinite(n)||n<0)return toast('Fecha o cantidad no válida');v.logs=v.logs||{};v.logs[o.date]={amount:n,note:o.note.trim()};toast(viceMet(v,v.logs[o.date])?'Registro guardado: objetivo cumplido':'Registro guardado; puedes retomar tu plan mañana')})},
vicedelete:i=>{const v=(S.vices||[]).find(x=>x.id===i);if(v&&confirm(`¿Eliminar “${v.name}” y su historial? Esta acción no se puede deshacer.`)){S.vices=S.vices.filter(x=>x.id!==i);save();render();toast('Hábito eliminado')}},
hsv:()=>{const nv=id=>{const v=$(id).value;return v===''?null:+v};S.hs[today()]={sleep:nv('#sl'),energy:nv('#en'),water:nv('#wt')};save();render();toast('Salud actualizada')},
imp:()=>{const i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=()=>{const f=i.files[0];f&&f.text().then(async t=>{let o;try{o=JSON.parse(t)}catch(e){return toast('Archivo no válido')}if(!validState(o))return toast('El archivo no tiene el formato de Mi Centro de Control');if(!confirm('Esto reemplaza todos tus datos actuales por los del archivo. ¿Continuar?'))return;if(!await Sync.backupOk('antes de importar un archivo JSON'))return;const v=S.view;S=o;mig();S.view=v;save();render();toast('Datos importados')})};i.click()},
wlock:()=>{if(U.wl){U.wl=false;return render()}if(confirm('Cambiar los pesos altera todo tu progreso general y sus comparaciones históricas. ¿Continuar?')){U.wl=true;render()}},wreset:()=>{S.w={ceo:30,proy:20,vida:20,salud:15,fin:15};save();render();toast('Pesos restaurados')},
why:i=>{const{c}=W();let h='';if(i==='ceo'){h=empGoals().map(g=>`<div class=row><span>${esc(g.t)}</span><span>${mv(g)} / ${g.mt} → ${clamp(Math.min(100,100*mv(g)/g.mt))}%</span></div>`).join('')||'<p class=sub>Aún no hay objetivos de Empresa con métrica.</p>';h+='<p class=sub>Promedio de tus objetivos de Empresa con métrica. Créalos en Objetivos.</p>'}else{const H7=days(...c).map(d=>S.hs[d]).filter(sleepOK),o=i==='proy'?proy(...c):i==='vida'?vida(...c):i==='salud'?{Ejercicio:clamp(100*S.wk.filter(w=>inW(w.date,...c)).length/(30/7*4)),'Meta de cigarrillos':cigOK(...c)??'sin datos','Sueño de 7 h o más':H7.length?clamp(100*H7.filter(q=>q.sleep>=7).length/H7.length):'sin datos'}:{'Progreso de metas financieras':finAt(today())};h=Object.entries(o).filter(k=>k[0]!=='all').map(k=>`<div class=row><span>${k[0]}</span><span>${k[1]}${typeof k[1]==='number'?'%':''}</span></div>`).join('')+'<p class=sub>Ventana de 30 días. El resultado es el promedio de estos componentes.</p>'}modal(`<h2>Cómo se calcula</h2>${h}<button class="btn g" data-a=close>Cerrar</button>`)},
addfg:()=>fgForm(),fgedit:i=>{const f=S.fg.find(x=>x.id===i);if(f)fgForm(f)},fgdel:i=>{if(confirm('¿Eliminar esta meta financiera? Los movimientos asociados se conservarán, pero dejarán de contar para esta meta.')){S.fg=S.fg.filter(f=>f.id!==i);save();render()}},
budgetadd:()=>budgetForm(),budgetedit:i=>{const b=S.budgets.find(x=>x.id===i);if(b)budgetForm(b)},budgetdel:i=>{if(confirm('¿Eliminar este presupuesto? Los movimientos no se borrarán.')){S.budgets=S.budgets.filter(b=>b.id!==i);save();render()}},
fin2:i=>{const dur=Math.max(1,Math.round((Date.now()-run.t0)/6e4)),ty=run.p.type;S.wk.push({id:uid(),date:today(),type:ty,dur,ex:run.log,dif:+i,ok:run.i>=run.p.ex.length?1:0});if(i==1)S.prog[ty]=Math.min(3,(S.prog[ty]||0)+1);if(i==3)S.prog[ty]=Math.max(-3,(S.prog[ty]||0)-1);daySch().filter(b=>b.k==='ej').forEach(b=>{(S.dl[today()]=S.dl[today()]||{})[b.id]='done'});closeM();save();render();toast('🏋️ Entrenamiento guardado: Vida y racha actualizadas')}};
document.addEventListener('error',e=>{const t=e.target;if(t&&t.tagName==='IMG'&&t.closest&&t.closest('[data-av]'))Sync.avatarBroken()},true);
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(el&&A[el.dataset.a])A[el.dataset.a](el.dataset.i,el)});
document.addEventListener('change',e=>{const el=e.target,c=el.dataset.c;if(!c)return;if(c==='finMonth'){U.finMonth=el.value;return render()}if(c==='finType'){U.finType=el.value;return render()}if(c==='finAllMonths'){U.finAllMonths=el.checked;return render()}if(c==='gest'){S.goals.find(g=>g.id===el.dataset.i).est=el.value;save();return render()}if(c==='ms'){const[i,k]=el.dataset.i.split('|');S.goals.find(g=>g.id===i).ms[+k].done=el.checked;save();return render()}if(c==='pf'){S.pf[el.dataset.i]=el.value;save();return}if(c==='tg'){S.tg[el.dataset.i]=Math.max(1,+el.value);save();return render()}if(c==='fs'){U.fs=el.value;return render()}if(c==='cost'){const x=S.co.find(z=>z.id===el.dataset.i);x.st=el.value;if(['Respondió','Entrevista'].includes(x.st)&&!S.tasks.some(t=>t.t.includes(x.n)&&!t.doneAt))S.tasks.push({id:uid(),t:(x.st==='Entrevista'?'Registrar problemas de la entrevista con ':'Agendar entrevista con ')+x.n,k:'ceo',cat:'',due:addD(today(),1),min:30,pri:3,st:'pendiente',doneAt:'',goal:'',dep:'',created:today()});toast('Estado actualizado');save();return render()}if(c==='prv'){S.pr.find(z=>z.id===el.dataset.i).v=el.value;save();return render()}if(c==='cigg')S.cig.goal=+el.value;else if(c==='w'){if(!U.wl)return;S.w[el.dataset.i]=Math.max(0,+el.value)}else S[c]=['level','min','goalSave','cap0'].includes(c)?+el.value:el.value;save();render()});
document.addEventListener('input',e=>{if(e.target.dataset.s==='finq'){U.finQuery=e.target.value;const p=e.target.selectionStart;render();const i=$('[data-s=finq]');if(i){i.focus();i.setSelectionRange(p,p)}return}if(e.target.dataset.s==='q'){U.q=e.target.value;const p=e.target.selectionStart;render();const i=$('[data-s=q]');i.focus();i.setSelectionRange(p,p)}});
$('#md').addEventListener('click',e=>{if(e.target.id==='md')closeM()});
let _day=today();const modalOpen=()=>$('#md').classList.contains('on');
const dayRoll=()=>{if(today()!==_day){_day=today();if(!modalOpen())render()}};setInterval(dayRoll,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)dayRoll()});
Sync.init({get:()=>S,set:s=>{let v=(S&&S.view)||s.view||localStorage.getItem('cc.view');S=s;mig();if(v&&P[v])S.view=v},fresh:k=>{const n=k==='demo'?demo():blank();n.view='inicio';return n},avatar:()=>{document.querySelectorAll('[data-av]').forEach(e=>{e.outerHTML=pfp(e.dataset.av)});const c=$('#pf-card');if(c)c.innerHTML=pfCard()},valid:validState,render:()=>{S.ach=S.ach||{};checkAch();render()},toast,esc,today});
